-- Lambdas over array columns, one array per row
select
  id,
  array_to_string(transform(nums, n ->
  n * 10),',') as tens,
  reduce(slice(nums, 2, cardinality(nums)), nums[1], (acc, n) ->
  acc + n, s -> s) as total,
  array_to_string(filter(words, w ->
  length(w) > 1),',') as long_words
from (values (1, ARRAY[1, 2], ARRAY['a', 'bb']), (2, ARRAY[3, 4, 5], ARRAY['ccc'])) as lists(id, nums, words)
order by id
;
select
  any_match(a, x ->
  x > 8) as some_large,
  any_match(a, x ->
  x > 9) as none_large,
