-- Prices in cents
select
  id,
  reduce(zip_with(prices, quantities, (p, q) ->
  p * q), 0, (acc, v) ->
  acc + v, s -> s) as total
from (values (1, ARRAY[250, 400], ARRAY[2, 3]), (2, ARRAY[100], ARRAY[5])) as orders(id, prices, quantities)
order by id
;
